-'use client';
-
-/**
- * 著陸頁截圖
- * 使用 APIFlash 服務捕獲網頁截圖
- *
- * @param url 要截圖的網頁 URL
- * @returns Base64 編碼的截圖資料
- */
-export async function captureLandingPage(url: string): Promise<string> {
-  const response = await fetch('/api/screenshot', {
-    method: 'POST',
-    headers: {
-      'Content-Type': 'application/json'
-    },
-    body: JSON.stringify({ url })
-  });
-
-  if (!response.ok) {
-    throw new Error(`Failed to capture screenshot: ${response.statusText}`);
-  }
-
-  const data = await response.json();
-  return data.screenshot;
-}
-
-/**
- * 著陸頁內容分析
- * 使用 Jina Reader 服務分析網頁內容
- *
- * @param url 要分析的網頁 URL
- * @returns 分析結果（標題、描述、URL、內容）
- */
-export async function analyzeLandingPage(url: string) {
-  const response = await fetch('/api/analyze', {
-    method: 'POST',
-    headers: {
-      'Content-Type': 'application/json'
-    },
-    body: JSON.stringify({ url })
-  });
-
-  if (!response.ok) {
-    throw new Error(`Failed to analyze landing page: ${response.statusText}`);
-  }
-
-  return response.json();
-}
